import sys, json, os, time, numpy as np

def read_instance(path):
    with open(path, 'r') as f:
        data = json.load(f)
    return data['n'], np.array(data['A'], dtype=np.int64), np.array(data['B'], dtype=np.int64)

def cost(p, A, B):
    return np.sum(A * B[p][:, p])

def main():
    try:
        if len(sys.argv) < 3:
            raise ValueError("Missing arguments")
        inst_path = sys.argv[1]
        budget = float(sys.argv[2])
        n, A, B = read_instance(inst_path)

        start = time.time()
        np.random.seed(42)
        perm = np.arange(n)
        np.random.shuffle(perm)
        best_perm = perm.copy()
        best_cost = cost(perm, A, B)

        T = 1.0
        alpha = 0.9995
        while time.time() - start < budget * 0.95:
            i, j = np.random.choice(n, 2, replace=False)
            perm[i], perm[j] = perm[j], perm[i]
            new_cost = cost(perm, A, B)
            delta = new_cost - best_cost
            if delta < 0 or np.random.rand() < np.exp(-delta / T):
                if new_cost < best_cost:
                    best_cost = new_cost
                    best_perm = perm.copy()
            else:
                perm[i], perm[j] = perm[j], perm[i]
            T *= alpha

        out = " ".join(str(x + 1) for x in best_perm)
        print(f"PERMUTATION: {out}")
    except Exception as e:
        print(f"ERROR: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
